{
  "name": "@amykit/plugin-slack",
  "version": "0.6.0",
  "description": "A Slack thread per piece of work, over the Web API, as the conversation port.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "plugins/slack"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "dependencies": {
    "@amykit/core": "^0.6.0"
  },
  "devDependencies": {
    "@amykit/test-fixtures": "^0.1.0"
  }
}

/** One HTTP exchange, small enough to script in a test. */
export interface HttpRequest {
  url: string;
  method: "GET" | "POST";
  headers: Record<string, string>;
  body?: string;
  /** Refuse the answer once its body passes this many bytes, while it arrives. */
  maxBytes?: number;
}

export interface HttpResponse {
  status: number;
  /** Lower-cased names. */
  headers: Record<string, string>;
  body: Uint8Array;
}

export type HttpTransport = (request: HttpRequest) => Promise<HttpResponse>;

/** An answer larger than the request allowed, refused before it was held whole. */
export class TooLarge extends Error {
  constructor(readonly limit: number) {
    super(`the answer is larger than ${limit} bytes`);
  }
}

export const fetchTransport: HttpTransport = async (request) => {
  const response = await fetch(request.url, {
    method: request.method,
    headers: request.headers,
    body: request.body,
  });
  const headers: Record<string, string> = {};
  response.headers.forEach((value, name) => {
    headers[name.toLowerCase()] = value;
  });
  return { status: response.status, headers, body: await readBody(response, request.maxBytes) };
};

/**
 * The body, counted as it arrives: a declared length over the limit is
 * refused unread, and a missing or wrong one is caught by the count.
 */
async function readBody(response: Response, maxBytes: number | undefined): Promise<Uint8Array> {
  if (maxBytes === undefined || !response.body) return new Uint8Array(await response.arrayBuffer());
  if (Number(response.headers.get("content-length") ?? 0) > maxBytes) {
    await response.body.cancel();
    throw new TooLarge(maxBytes);
  }
  const chunks: Uint8Array[] = [];
  let total = 0;
  const reader = response.body.getReader();
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    total += value.byteLength;
    if (total > maxBytes) {
      await reader.cancel();
      throw new TooLarge(maxBytes);
    }
    chunks.push(value);
  }
  const body = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    body.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return body;
}

export const SLACK_API = "https://slack.com/api";

/** What one Web API method answered, with the headers that carry the scopes. */
export interface SlackAnswer {
  body: Record<string, unknown>;
  headers: Record<string, string>;
}

export interface SlackApiOptions {
  transport?: HttpTransport;
  sleep?: (ms: number) => Promise<void>;
  /** How many times a `429` is waited out before the call fails. */
  maxRateLimitRetries?: number;
  /** How long a `429` that names no `Retry-After` is waited out. */
  defaultRetryAfterSeconds?: number;
}

/**
 * Slack's answer when it waits without saying for how long: the one-a-minute
 * limit on `conversations.replies` is the one this plugin is likeliest to hit.
 */
export const DEFAULT_RETRY_AFTER_S = 60;

export const DEFAULT_RATE_LIMIT_RETRIES = 5;

/**
 * The Web API, and only the Web API.
 *
 * No Socket Mode: Slack hands each event to one of an app's connections, so
 * a connection opened here would take events from whatever else is connected.
 */
export class SlackApi {
  private readonly transport: HttpTransport;
  private readonly sleep: (ms: number) => Promise<void>;
  private readonly maxRetries: number;
  private readonly defaultRetryAfterS: number;

  constructor(
    private readonly token: string,
    options: SlackApiOptions = {},
  ) {
    this.transport = options.transport ?? fetchTransport;
    this.sleep = options.sleep ?? ((ms) => new Promise((resolve) => setTimeout(resolve, ms)));
    this.maxRetries = options.maxRateLimitRetries ?? DEFAULT_RATE_LIMIT_RETRIES;
    this.defaultRetryAfterS = options.defaultRetryAfterSeconds ?? DEFAULT_RETRY_AFTER_S;
  }

  /** Calls a method form-encoded, which every method accepts, and refuses `ok: false`. */
  async call(method: string, args: Record<string, string | undefined> = {}): Promise<SlackAnswer> {
    const form = new URLSearchParams();
    for (const [key, value] of Object.entries(args)) if (value !== undefined) form.set(key, value);

    const response = await this.send({
      url: `${SLACK_API}/${method}`,
      method: "POST",
      headers: {
        Authorization: `Bearer ${this.token}`,
        "Content-Type": "application/x-www-form-urlencoded",
      },
      body: form.toString(),
    });
    if (response.status !== 200) throw new Error(`slack ${method} answered HTTP ${response.status}`);

    const body = JSON.parse(new TextDecoder().decode(response.body)) as Record<string, unknown>;
    if (body.ok !== true) {
      // `missing_scope` carries the scope it wanted, which is the fix.
      const needed = typeof body.needed === "string" ? ` (needs ${body.needed})` : "";
      throw new Error(`slack ${method} refused: ${String(body.error ?? "unknown error")}${needed}`);
    }
    return { body, headers: response.headers };
  }

  /**
   * A file's bytes, with the bot token.
   *
   * Only ever to Slack's own hosts over https: the URL comes out of a message,
   * and the token must not follow one anywhere else.
   */
  async download(url: string, maxBytes?: number): Promise<Uint8Array> {
    const parsed = new URL(url);
    if (parsed.protocol !== "https:" || !isSlackHost(parsed.hostname)) {
      throw new Error(`refusing to send the slack token to ${parsed.origin}`);
    }
    const response = await this.send({ url, method: "GET", headers: { Authorization: `Bearer ${this.token}` }, maxBytes });
    if (response.status !== 200) throw new Error(`slack file ${parsed.pathname} answered HTTP ${response.status}`);
    // Checked again here for a transport that does not honour the limit.
    if (maxBytes !== undefined && response.body.byteLength > maxBytes) throw new TooLarge(maxBytes);
    return response.body;
  }

  private async send(request: HttpRequest): Promise<HttpResponse> {
    for (let attempt = 0; ; attempt++) {
      const response = await this.transport(request);
      if (response.status !== 429) return response;
      if (attempt >= this.maxRetries) {
        throw new Error(`slack kept rate limiting ${request.url} after ${attempt + 1} tries`);
      }
      await this.sleep(retryAfterMs(response.headers["retry-after"], this.defaultRetryAfterS));
    }
  }
}

function retryAfterMs(header: string | undefined, fallbackS: number): number {
  const seconds = header?.trim() ? Number(header) : Number.NaN;
  return (Number.isFinite(seconds) && seconds >= 0 ? seconds : fallbackS) * 1000;
}

function isSlackHost(hostname: string): boolean {
  return hostname === "slack.com" || hostname.endsWith(".slack.com");
}

import { createHash, randomUUID } from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { Ask, Conversation, Reply, ThreadRef } from "@amykit/core";
import { SlackApi, TooLarge } from "./SlackApi.js";
import { ThreadMap, privateDirectory } from "./ThreadMap.js";

export interface SlackConversationOptions {
  /** A channel id, not a name. */
  channel: string;
  /** The only user whose replies are answers. */
  operator: string;
  /** Where the thread map and downloaded files live. */
  directory: string;
  /** How long to wait for another process opening a thread. */
  lockWaitMs?: number;
  /** How long a claim on a thread holds without being renewed. */
  leaseMs?: number;
  /** The largest attachment downloaded; a larger one is named in the reply instead. */
  maxFileBytes?: number;
  /**
   * Days a downloaded file or a thread's memory stays unused before it is
   * pruned; `0` keeps everything.
   */
  retentionDays?: number;
  /**
   * The reactions the operator puts on their own reply to mark what it is,
   * by emoji name. A reply without one carries no kind, and the workflow's
   * policy reads it.
   */
  marks?: { decision: string; discussion: string };
  /** Inspection reads existing state but never creates or changes it. */
  readOnly?: boolean;
  now?: () => Date;
}

/** What `amy doctor` prints for this plugin, one line per question. */
export interface SlackCheck {
  label: string;
  ok: boolean;
  detail?: string;
}

interface SlackFile {
  id?: string;
  name?: string;
  size?: number;
  url_private?: string;
  url_private_download?: string;
}

interface SlackReaction {
  name?: string;
  users?: string[];
  count?: number;
}

interface AnswerVerdict {
  chosen?: string[];
  ambiguous: boolean;
  observed: string[];
}

interface SlackMessage {
  ts?: string;
  thread_ts?: string;
  metadata?: { event_type?: string; event_payload?: Record<string, unknown> };
  user?: string;
  bot_id?: string;
  subtype?: string;
  text?: string;
  files?: SlackFile[];
  reactions?: SlackReaction[];
}

/**
 * One Slack thread per piece of work, in one channel.
 *
 * The thread is remembered on disk by work id, so a restart posts into the
 * thread it already opened instead of opening a second one. A root Slack
 * accepted just before a crash is found again in the channel's history
 * rather than posted twice.
 */
/** Large enough for any screenshot, small enough that a daemon never holds a video. */
const DEFAULT_MAX_FILE_BYTES = 25 * 1024 * 1024;

/** Long enough for an operator's holiday, short enough that screenshots do not pile up. */
export const DEFAULT_RETENTION_DAYS = 30;

/** Pruning walks the state directory, so it happens at most this often. */
const PRUNE_EVERY_MS = 60 * 60 * 1000;

const DAY_MS = 24 * 60 * 60 * 1000;

/** A reaction whose list of users is too short to say who is on it. */
const UNKNOWN = Symbol("unknown");

/** ✅ settles it, 💬 asks something first. */
export const DEFAULT_MARKS = { decision: "white_check_mark", discussion: "speech_balloon" } as const;

/** What marks a root as amy's, and whose work it opened. */
const ROOT_EVENT = "amy_work_thread";
const ASK_EVENT = "amy_ask";
const ASK_FALLBACK_EVENT = "amy_ask_fallback";
const ASK_AMBIGUOUS_EVENT = "amy_ask_ambiguous";
const ASK_TAKEN_EVENT = "amy_ask_taken";
const KEYCAPS = ["one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "keycap_ten"] as const;
const APPROVAL_REACTIONS = ["white_check_mark", "x"] as const;
const SUBMIT_REACTION = "white_check_mark";

export class SlackConversation implements Conversation {
  readonly asks = true as const;
  private readonly threads: ThreadMap;
  private readonly filesDirectory: string;
  private readonly opening = new Map<string, Promise<ThreadRef>>();
  private botUser?: Promise<string>;
  private prunedAt = Number.NEGATIVE_INFINITY;

  constructor(
    private readonly api: SlackApi,
    private readonly options: SlackConversationOptions,
  ) {
    this.threads = new ThreadMap(options.directory, {
      maxWaitMs: options.lockWaitMs,
      leaseMs: options.leaseMs,
      readOnly: options.readOnly,
      // A root replaced in another channel takes its downloads with it.
      onDisplaced: (ts) => this.dropFiles(ts),
    });
    this.filesDirectory = path.join(options.directory, "files");
    // The operator's screenshots, fetched with the bot's token: private.
    if (!options.readOnly) privateDirectory(this.filesDirectory);
  }

  open(workId: string, title: string): Promise<ThreadRef> {
    let known: string | undefined;
    try {
      // Known first, which marks it used, so the prune after it keeps it.
      known = this.threads.known(workId, this.options.channel);
    } catch (error) {
      // A promise-returning method rejects; it does not throw at the caller.
      return Promise.reject(error instanceof Error ? error : new Error(String(error)));
    }
    this.pruneNowAndThen();
    if (known) return Promise.resolve({ id: known });

    // Two looks at the same work in one process must not open two threads.
    const pending = this.opening.get(workId);
    if (pending) return pending;
    const opened = this.startThread(workId, title).finally(() => this.opening.delete(workId));
    this.opening.set(workId, opened);
    return opened;
  }

  async post(thread: ThreadRef, message: { text: string; files?: string[]; ask?: Ask }): Promise<string> {
    if (message.files?.length) {
      throw new Error("@amykit/plugin-slack does not upload files; post their paths as text");
    }
    this.threads.used(thread.id);
    this.pruneNowAndThen();
    if (!message.ask) return this.postText(thread.id, message.text);

    const ask = message.ask;
    if (!validAsk(ask)) return this.postAskFallback(thread.id, message.text, ask);
    if (ask.form !== "approval" && ask.answers.length > KEYCAPS.length) {
      return this.postAskFallback(thread.id, message.text, ask);
    }
    const { body } = await this.api.call("chat.postMessage", {
      channel: this.options.channel,
      thread_ts: thread.id,
      text: renderAsk(message.text, ask, false),
      metadata: askMetadata(ASK_EVENT, ask),
    });
    const ts = String(body.ts);
    try {
      this.rememberAskedFrom(thread.id, ts);
      for (const name of reactionsFor(ask)) {
        await this.api.call("reactions.add", { channel: this.options.channel, timestamp: ts, name });
      }
      return ts;
    } catch {
      // Typed replies remain available when Slack will not accept controls.
      return this.postAskFallback(thread.id, message.text, ask);
    }
  }

  async replies(thread: ThreadRef, since: string): Promise<Reply[]> {
    const after = instantToMicros(since);
    if (Number.isNaN(after)) throw new Error(`replies since ${since}: not an instant`);
    this.threads.used(thread.id);
    this.pruneNowAndThen();
    const bot = await this.botUserId();
    // A later copy of the same ask must see the earlier decision. Slack has
    // no reaction timestamp, so recover the thread's ask messages instead
    // of retaining an accepted answer in process memory. Where amy recorded
    // the first ask it posted here, one read from there holds both the asks
    // and what is recent: conversations.replies may be limited to one call
    // a minute, so a look makes one.
    const askedFrom = this.askedFrom(thread.id);
    const read = askedFrom === undefined
      ? await this.threadMessages(thread.id, after)
      : await this.threadMessages(thread.id, Math.min(after, askedFrom), true);
    const recent = askedFrom === undefined ? read : read.filter((message) => message.ts !== undefined && tsToMicros(message.ts) > after);
    // Metadata is anybody's to attach: an ask, or the notice amy took one,
    // is read only from a message this bot wrote, so another app cannot
    // turn the operator's reaction into an answer to amy's question.
    const amys = (messages: SlackMessage[]) => messages.filter((message) => message.metadata === undefined || message.user === bot);
    // With no record (an ask from before amy kept one), a recent ask still
    // sends the look back for the whole thread, as it always did.
    const unrecorded = askedFrom === undefined && recent.some((message) => message.user === bot && readAsk(message) !== undefined);
    const messages = amys(unrecorded ? await this.threadMessages(thread.id, 0) : read);
    const answers = await this.askedReplies(thread.id, after, messages);

    for (const message of recent) {
      if (!this.isOperatorAnswer(message, thread.id, bot)) continue;
      const at = tsToMicros(message.ts!);
      if (at <= after) continue;
      const { paths, skipped } = await this.downloadAll(thread.id, message.files ?? []);
      const kind = await this.kindOf(message);
      answers.push({
        at: microsToInstant(at),
        author: message.user!,
        text: [message.text ?? "", ...skipped].filter(Boolean).join("\n"),
        files: paths,
        ...(kind ? { kind } : {}),
      });
    }
    return answers.sort((a, b) => a.at.localeCompare(b.at));
  }

  /**
   * Whether the token can do what this plugin does, asked of Slack itself.
   *
   * `auth.test` for the token, its `x-oauth-scopes` header for the scopes,
   * and `conversations.info` for whether the channel is one the bot can see
   * — which also says whether the history scope it needs is the public or
   * the private one.
   */
  async checks(): Promise<SlackCheck[]> {
    try {
      const { body, headers } = await this.api.call("auth.test");
      const scopes = (headers["x-oauth-scopes"] ?? "").split(",").map((scope) => scope.trim()).filter(Boolean);
      const checks: SlackCheck[] = [{ label: "slack token", ok: true, detail: `${String(body.user)} in ${String(body.team)}` }];
      return checks.concat(await this.channelChecks(scopes));
    } catch (error) {
      return [{ label: "slack token", ok: false, detail: messageOf(error) }];
    }
  }

  /**
   * Forgets one piece of work: its thread's memory and every file downloaded
   * from it. The thread stays in Slack; the next `open` starts a new one.
   */
  forget(workId: string): void {
    const ts = this.threads.forget(workId);
    if (ts) this.dropFiles(ts);
  }

  /**
   * Removes what nobody used within the retention: a downloaded file, which
   * the next read of its reply fetches again, and a thread's memory, whose
   * files go with it. Returns how many of each went.
   */
  prune(now: Date = this.clock()): { threads: number; files: number } {
    // Whatever a forget marked and did not get to remove goes first, even
    // when retention keeps everything else: that was a decision, not an age.
    sweepForgotten(this.filesDirectory);
    const days = this.options.retentionDays ?? DEFAULT_RETENTION_DAYS;
    if (days <= 0) return { threads: 0, files: 0 };
    const cutoff = now.getTime() - days * DAY_MS;

    const threads = this.threads.prune(cutoff);
    for (const ts of threads) this.dropFiles(ts);
    return { threads: threads.length, files: pruneFiles(this.filesDirectory, cutoff) };
  }

  private clock(): Date {
    return this.options.now?.() ?? new Date();
  }

  /** Where one thread's downloads live, so forgetting it takes them too. */
  private threadFiles(ts: string): string {
    return path.join(this.filesDirectory, safeName(ts));
  }

  /** Beside the thread's files, not in them, so removing those leaves it. */
  private forgottenMarker(ts: string): string {
    return path.join(this.filesDirectory, `${safeName(ts)}.forgotten`);
  }

  /**
   * Marks the thread forgotten, then removes its files. The marker is what a
   * download still in flight — in this process or another — reads after it
   * publishes, so it cannot bring a forgotten thread's file back.
   */
  private dropFiles(ts: string): void {
    privateDirectory(this.filesDirectory);
    fs.writeFileSync(this.forgottenMarker(ts), "", { mode: 0o600 });
    fs.rmSync(this.threadFiles(ts), { recursive: true, force: true });
    fs.rmSync(this.answerDirectory(ts), { recursive: true, force: true });
  }

  /** Throttled, and never the reason a call fails: pruning is housekeeping. */
  private pruneNowAndThen(): void {
    const now = this.clock();
    if (now.getTime() - this.prunedAt < PRUNE_EVERY_MS) return;
    this.prunedAt = now.getTime();
    try {
      this.prune(now);
    } catch {
      // A file another process removed first, or one still being written.
    }
  }

  private async postText(threadTs: string, text: string): Promise<string> {
    const { body } = await this.api.call("chat.postMessage", { channel: this.options.channel, thread_ts: threadTs, text });
    return String(body.ts);
  }

  private async postAskFallback(threadTs: string, text: string, ask: Ask): Promise<string> {
    const { body } = await this.api.call("chat.postMessage", {
      channel: this.options.channel,
      thread_ts: threadTs,
      text: renderAsk(text, ask, true),
      metadata: askMetadata(ASK_FALLBACK_EVENT, ask),
    });
    return String(body.ts);
  }

  /** Reconstruct answers from Slack every time; no accepted-answer cache survives a process. */
  private async askedReplies(threadTs: string, after: number, messages: SlackMessage[]): Promise<Reply[]> {
    const asks = messages.map(readAsk).filter((ask): ask is { message: SlackMessage; ask: Ask } => ask !== undefined);
    const taken = new Set<string>();
    const replies: Reply[] = [];
    for (const entry of asks.sort((a, b) => tsToMicros(a.message.ts!) - tsToMicros(b.message.ts!))) {
      const remembered = this.rememberedAnswer(threadTs, entry.ask.id);
      // Re-read an accepted ask too: its decision is immutable, but a later
      // complete, different mark still deserves the once-only acknowledgement.
      // Marks Slack cannot fully list block a first answer, never a saved
      // one: the remembered answer is replayed and nothing new is read.
      const verdict: AnswerVerdict = await this.answerOf(entry.message, entry.ask).catch((error: unknown): AnswerVerdict => {
        if (remembered) return { ambiguous: false, observed: [] };
        throw error;
      });
      const accepted = await this.acceptedAnswer(threadTs, messages, entry, remembered, verdict);
      if (!accepted) continue;
      const chosen = accepted.chosen;
      // Another copy of the ask carries the answer: this one is replayed by
      // nothing, and a complete mark on it is a later answer, told once.
      if (accepted.messageTs !== entry.message.ts) {
        if (verdict.chosen || verdict.ambiguous) await this.acknowledgeTaken(threadTs, messages, entry.ask, chosen);
        continue;
      }
      if (this.hasChangedAnswer(remembered, verdict)) await this.acknowledgeTaken(threadTs, messages, entry.ask, chosen);
      if (taken.has(entry.ask.id)) {
        await this.acknowledgeTaken(threadTs, messages, entry.ask, chosen);
        continue;
      }
      taken.add(entry.ask.id);
      // An answer saved before amy dated it carries its ask's time instead.
      const acceptedAt = accepted.acceptedAt === undefined ? tsToMicros(accepted.messageTs) : instantToMicros(accepted.acceptedAt);
      if (acceptedAt > after) {
        replies.push({ at: microsToInstant(acceptedAt), author: this.options.operator, text: entry.ask.prompt, files: [], kind: "decision", answer: { ask: entry.ask.id, chosen } });
      }
    }
    return replies;
  }

  /** The answer this ask holds after this look, if any: the remembered one, or the first complete one seen now. */
  private async acceptedAnswer(
    threadTs: string,
    messages: SlackMessage[],
    entry: { message: SlackMessage; ask: Ask },
    remembered: { chosen: string[]; messageTs: string; acceptedAt?: string } | undefined,
    verdict: AnswerVerdict,
  ): Promise<{ chosen: string[]; messageTs: string; acceptedAt?: string } | undefined> {
    if (verdict.ambiguous) {
      await this.explainAmbiguity(threadTs, messages, entry.ask, verdict.observed);
      // A later conflict cannot revoke the durable first answer: replay it
      // so a look that previously parked still has the decision to apply.
      if (remembered) await this.acknowledgeTaken(threadTs, messages, entry.ask, remembered.chosen);
      return remembered;
    }
    if (!verdict.chosen) return remembered;
    return remembered ?? this.rememberAnswer(threadTs, entry.ask.id, verdict.chosen, entry.message.ts!);
  }

  /** The first complete answer is immutable once seen, even if its reaction changes later. */
  protected rememberedAnswer(threadTs: string, askId: string): { chosen: string[]; messageTs: string; acceptedAt?: string } | undefined {
    try {
      const state = JSON.parse(fs.readFileSync(this.answerFile(threadTs, askId), "utf-8")) as { chosen?: unknown; messageTs?: unknown; acceptedAt?: unknown };
      if (!Array.isArray(state.chosen) || !state.chosen.every((chosen) => typeof chosen === "string") || typeof state.messageTs !== "string") return undefined;
      return { chosen: state.chosen, messageTs: state.messageTs, ...(typeof state.acceptedAt === "string" ? { acceptedAt: state.acceptedAt } : {}) };
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined;
      throw error;
    }
  }

  /** Creates the decision once; a competing reader adopts the value written first. */
  private rememberAnswer(threadTs: string, askId: string, chosen: string[], messageTs: string): { chosen: string[]; messageTs: string; acceptedAt?: string } {
    const file = this.answerFile(threadTs, askId);
    fs.mkdirSync(path.dirname(file), { recursive: true, mode: 0o700 });
    const staged = path.join(path.dirname(file), `.${randomUUID()}.partial`);
    const handle = fs.openSync(staged, "wx", 0o600);
    try {
      // When amy first saw it, not when it asked: an ask posted before a
      // look's since can still be answered after it.
      fs.writeFileSync(handle, JSON.stringify({ chosen, messageTs, acceptedAt: this.clock().toISOString() }));
      fs.fsyncSync(handle);
    } finally {
      fs.closeSync(handle);
    }
    try {
      fs.linkSync(staged, file);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
    } finally {
      fs.rmSync(staged, { force: true });
    }
    return this.rememberedAnswer(threadTs, askId) ?? { chosen, messageTs, acceptedAt: this.clock().toISOString() };
  }

  /** The first ask amy posted in this thread, as microseconds, if it kept one. */
  private askedFrom(threadTs: string): number | undefined {
    try {
      const ts = fs.readFileSync(path.join(this.answerDirectory(threadTs), "asked-from"), "utf-8").trim();
      const micros = tsToMicros(ts);
      return Number.isNaN(micros) ? undefined : micros;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined;
      throw error;
    }
  }

  /** Keeps the earliest ask's ts; a later ask leaves it where it is. */
  private rememberAskedFrom(threadTs: string, ts: string): void {
    const earlier = this.askedFrom(threadTs);
    if (earlier !== undefined && earlier <= tsToMicros(ts)) return;
    fs.mkdirSync(this.answerDirectory(threadTs), { recursive: true, mode: 0o700 });
    fs.writeFileSync(path.join(this.answerDirectory(threadTs), "asked-from"), ts, { mode: 0o600 });
  }

  private answerFile(threadTs: string, askId: string): string {
    return path.join(this.answerDirectory(threadTs), `${createHash("sha256").update(askId).digest("hex")}.json`);
  }

  private answerDirectory(threadTs: string): string {
    return path.join(this.options.directory, "answers", safeName(threadTs));
  }

  private hasChangedAnswer(remembered: { chosen: string[] } | undefined, verdict: AnswerVerdict): boolean {
    return remembered !== undefined && (verdict.ambiguous || (verdict.chosen !== undefined && !sameAnswers(remembered.chosen, verdict.chosen)));
  }

  private async answerOf(message: SlackMessage, ask: Ask): Promise<AnswerVerdict> {
    const names = reactionsFor(ask);
    const reactions = await this.completeReactions(message, names);
    if (names.some((name) => this.marked(reactions, name) === UNKNOWN)) throw new Error(`Slack did not identify every reaction on ask ${ask.id}`);
    const marked = names.filter((name) => this.marked(reactions, name) === true);
    if (ask.form === "approval") {
      return { chosen: marked.length === 1 ? [marked[0] === "white_check_mark" ? "approve" : "reject"] : undefined, ambiguous: marked.length > 1, observed: marked };
    }
    const selected = KEYCAPS.slice(0, ask.answers.length).filter((name) => marked.includes(name));
    if (ask.form === "choice" && selected.length > 1) return { ambiguous: true, observed: selected };
    if (ask.form === "choices" && !marked.includes(SUBMIT_REACTION)) return { ambiguous: false, observed: selected };
    if (ask.form === "choice" && selected.length !== 1) return { ambiguous: false, observed: selected };
    return { chosen: selected.map((name) => ask.answers[KEYCAPS.indexOf(name)]!), ambiguous: false, observed: selected };
  }

  private async completeReactions(message: SlackMessage, names: readonly string[]): Promise<SlackReaction[]> {
    const listed = message.reactions ?? [];
    if (names.some((name) => this.marked(listed, name) === UNKNOWN)) return this.allReactions(message.ts!);
    return listed;
  }

  private async explainAmbiguity(threadTs: string, messages: SlackMessage[], ask: Ask, observed: string[]): Promise<void> {
    if (hasAskEvent(messages, ASK_AMBIGUOUS_EVENT, ask.id)) return;
    await this.api.call("chat.postMessage", { channel: this.options.channel, thread_ts: threadTs, text: `I saw conflicting answers for ${ask.id}: ${observed.join(", ")}. Please leave one answer.`, metadata: askMetadata(ASK_AMBIGUOUS_EVENT, ask) });
    rememberAskEvent(messages, ASK_AMBIGUOUS_EVENT, ask);
  }

  private async acknowledgeTaken(threadTs: string, messages: SlackMessage[], ask: Ask, chosen: string[]): Promise<void> {
    if (hasAskEvent(messages, ASK_TAKEN_EVENT, ask.id)) return;
    await this.api.call("chat.postMessage", { channel: this.options.channel, thread_ts: threadTs, text: `Amy already took ${ask.id}: ${chosen.join(", ")}.`, metadata: askMetadata(ASK_TAKEN_EVENT, ask) });
    rememberAskEvent(messages, ASK_TAKEN_EVENT, ask);
  }

  private async channelChecks(scopes: readonly string[]): Promise<SlackCheck[]> {
    const label = `slack channel ${this.options.channel}`;
    try {
      const { body } = await this.api.call("conversations.info", { channel: this.options.channel });
      const channel = (body.channel ?? {}) as { name?: string; is_private?: boolean; is_member?: boolean };
      const isPrivate = channel.is_private === true;
      const name = `#${channel.name ?? "?"}`;
      // A public channel can be read without joining it, but `chat:write`
      // only posts where the bot is a member.
      const checks: SlackCheck[] = [
        channel.is_member === false
          ? { label, ok: false, detail: `the bot is not in ${name}; invite it there with /invite` }
          : { label, ok: true, detail: name },
      ];
      const needed = [
        "chat:write",
        isPrivate ? "groups:read" : "channels:read",
        isPrivate ? "groups:history" : "channels:history",
        "files:read",
        "reactions:write",
        "reactions:read",
      ];
      const missing = needed.filter((scope) => !scopes.includes(scope));
      checks.push({
        label: "slack scopes",
        ok: missing.length === 0,
        detail: missing.length === 0 ? needed.join(", ") : `missing ${missing.join(", ")}`,
      });
      return checks;
    } catch (error) {
      return [{ label, ok: false, detail: messageOf(error) }];
    }
  }

  /**
   * Exactly one process posts a root per attempt; an attempt that follows
   * one that may have reached Slack looks for that root before posting.
   */
  private async startThread(workId: string, title: string): Promise<ThreadRef> {
    const channel = this.options.channel;
    const ts = await this.threads.open(workId, channel, async (recoverSince) => {
      const recovered = recoverSince === undefined ? undefined : await this.findRoot(workId, recoverSince);
      if (recovered) return { ts: recovered, posted: false };
      const { body } = await this.api.call("chat.postMessage", {
        channel,
        text: title,
        metadata: JSON.stringify({ event_type: ROOT_EVENT, event_payload: { work_id: workId } }),
      });
      return { ts: String(body.ts), posted: true };
    }, async (superseded) => {
      // Best effort: a root that cannot be deleted is a stray message in the
      // channel, never a second thread this machine remembers.
      await this.api.call("chat.delete", { channel, ts: superseded }).catch(() => undefined);
    });
    return { id: ts };
  }

  /**
   * The root this bot posted for this work since `since`, if Slack took one.
   *
   * Matched by the work id carried in the root's metadata, never by its
   * text: two items can share a title, and a title can change.
   */
  private async findRoot(workId: string, since: number): Promise<string | undefined> {
    const bot = await this.botUserId();
    const messages = await this.pages("conversations.history", {
      channel: this.options.channel,
      oldest: msToTs(since - 1000),
      include_all_metadata: "true",
    });
    const root = messages.find((message) =>
      message.user === bot &&
      (!message.thread_ts || message.thread_ts === message.ts) &&
      message.metadata?.event_type === ROOT_EVENT &&
      message.metadata.event_payload?.work_id === workId);
    return root?.ts;
  }

  /** Every message in the thread after `afterMicros`, or from it on when `inclusive`: Slack leaves the bound out by default. */
  private threadMessages(ts: string, afterMicros: number, inclusive = false): Promise<SlackMessage[]> {
    return this.pages("conversations.replies", {
      channel: this.options.channel, ts, oldest: microsToTs(afterMicros), include_all_metadata: "true",
      ...(inclusive ? { inclusive: "true" } : {}),
    });
  }

  private async pages(method: string, args: Record<string, string>): Promise<SlackMessage[]> {
    const messages: SlackMessage[] = [];
    let cursor: string | undefined;
    do {
      const { body } = await this.api.call(method, { ...args, cursor });
      messages.push(...((body.messages ?? []) as SlackMessage[]));
      const next = (body.response_metadata as { next_cursor?: string } | undefined)?.next_cursor;
      cursor = body.has_more === true && next ? next : undefined;
    } while (cursor);
    return messages;
  }

  /**
   * What the operator marked their reply as, by their own reaction on it and
   * nobody else's — never by its text. Both marks read as the decision, the
   * one that moves the work, because a person who put both meant to be done.
   * Re-read on every look, so marking a reply after it was answered counts.
   *
   * Slack may list only some of a reaction's users while `count` holds them
   * all. Only a mark whose answer could still change the kind is asked again
   * in full, and a reply the operator may have marked is never read as
   * unmarked: if the full list still cannot say, the read fails and says why.
   */
  private async kindOf(message: SlackMessage): Promise<Reply["kind"]> {
    const listed = this.kindFrom(message.reactions ?? []);
    if (listed !== UNKNOWN) return listed;
    const full = this.kindFrom(await this.allReactions(message.ts!));
    if (full !== UNKNOWN) return full;
    throw new Error(`cannot tell whether the operator marked reply ${message.ts}: Slack lists only part of who reacted to it`);
  }

  /** The kind these reactions say, or UNKNOWN when a list too short to tell could change it. */
  private kindFrom(reactions: readonly SlackReaction[]): Reply["kind"] | typeof UNKNOWN {
    const marks = this.options.marks ?? DEFAULT_MARKS;
    const decision = this.marked(reactions, marks.decision);
    if (decision === true) return "decision";
    const discussion = this.marked(reactions, marks.discussion);
    if (decision === UNKNOWN || discussion === UNKNOWN) return UNKNOWN;
    return discussion ? "discussion" : undefined;
  }

  /** Whether the operator put this reaction on, or UNKNOWN when Slack's list is short and leaves them out. */
  private marked(reactions: readonly SlackReaction[], name: string): boolean | typeof UNKNOWN {
    const reaction = reactions.find((candidate) => candidate.name === name);
    if (!reaction) return false;
    const users = reaction.users ?? [];
    if (users.includes(this.options.operator)) return true;
    return (reaction.count ?? users.length) > users.length ? UNKNOWN : false;
  }

  private async allReactions(ts: string): Promise<SlackReaction[]> {
    try {
      const { body } = await this.api.call("reactions.get", { channel: this.options.channel, timestamp: ts, full: "true" });
      return ((body.message as { reactions?: SlackReaction[] } | undefined)?.reactions ?? []);
    } catch (error) {
      throw new Error(`cannot tell whether the operator marked reply ${ts}: ${messageOf(error)}`, { cause: error });
    }
  }

  /** By author id, never by a marker in the text. */
  private isOperatorAnswer(message: SlackMessage, threadTs: string, bot: string): boolean {
    if (!message.ts || message.ts === threadTs) return false;
    if (message.bot_id || message.user === bot) return false;
    if (message.subtype && message.subtype !== "thread_broadcast" && message.subtype !== "file_share") return false;
    return message.user === this.options.operator;
  }

  /** Cached once known; a failure is not, so the next poll asks again. */
  private botUserId(): Promise<string> {
    this.botUser ??= this.api.call("auth.test").then(
      ({ body }) => String(body.user_id),
      (error: unknown) => {
        this.botUser = undefined;
        throw error;
      },
    );
    return this.botUser;
  }

  /**
   * The attachments as local paths, and a line naming each one too large to
   * fetch — declared so by Slack, or found so while it arrived — so the
   * reader knows a file was there rather than never seeing it.
   */
  private async downloadAll(threadTs: string, files: readonly SlackFile[]): Promise<{ paths: string[]; skipped: string[] }> {
    const limit = this.options.maxFileBytes ?? DEFAULT_MAX_FILE_BYTES;
    const paths: string[] = [];
    const skipped: string[] = [];
    for (const file of files) {
      const url = file.url_private_download ?? file.url_private;
      if (!file.id || !url) continue;
      const name = file.name ?? file.id;
      const tooLarge = `[${name} was not downloaded: it is larger than ${limit} bytes]`;
      if ((file.size ?? 0) > limit) {
        skipped.push(tooLarge);
        continue;
      }
      try {
        const kept = await this.download(threadTs, path.join(this.threadFiles(threadTs), safeName(file.id), safeName(name)), url, limit);
        if (kept) paths.push(kept);
      } catch (error) {
        if (!(error instanceof TooLarge)) throw error;
        skipped.push(tooLarge);
      }
    }
    return { paths, skipped };
  }

  /** The file's local path, or nothing when its thread was forgotten. */
  private async download(threadTs: string, target: string, url: string, limit: number): Promise<string | undefined> {
    if (fs.existsSync(this.forgottenMarker(threadTs))) return undefined;
    if (keptAgain(target)) return target;
    const bytes = await this.api.download(url, limit);
    fs.mkdirSync(path.dirname(target), { recursive: true, mode: 0o700 });
    // Staged and renamed, so a path that exists is always a whole file.
    const partial = `${target}.${randomUUID()}.partial`;
    try {
      fs.writeFileSync(partial, bytes, { flag: "wx", mode: 0o600 });
      fs.renameSync(partial, target);
    } finally {
      fs.rmSync(partial, { force: true });
    }
    // Published first, checked after: a forget that landed while the bytes
    // were arriving is seen here, whichever of the two finished first.
    if (fs.existsSync(this.forgottenMarker(threadTs))) {
      fs.rmSync(this.threadFiles(threadTs), { recursive: true, force: true });
      return undefined;
    }
    return target;
  }
}

function askMetadata(event: string, ask: Ask): string {
  return JSON.stringify({ event_type: event, event_payload: { ask } });
}

function readAsk(message: SlackMessage): { message: SlackMessage; ask: Ask } | undefined {
  if (message.metadata?.event_type !== ASK_EVENT || !message.ts) return undefined;
  const ask = message.metadata.event_payload?.ask;
  if (!isAsk(ask)) return undefined;
  return { message, ask };
}

function isAsk(value: unknown): value is Ask {
  if (!value || typeof value !== "object") return false;
  const ask = value as Partial<Ask>;
  if (typeof ask.id !== "string" || typeof ask.prompt !== "string" || !Array.isArray(ask.answers)) return false;
  if (ask.form === "approval") return ask.answers.length === 2 && ask.answers[0] === "approve" && ask.answers[1] === "reject";
  return ask.form === "choice" || ask.form === "choices";
}

function hasAskEvent(messages: readonly SlackMessage[], event: string, askId: string): boolean {
  return messages.some((message) => message.metadata?.event_type === event && readMetadataAskId(message) === askId);
}

/** Make a successful notice visible to duplicate asks in this same poll. */
function rememberAskEvent(messages: SlackMessage[], event: string, ask: Ask): void {
  messages.push({ metadata: { event_type: event, event_payload: { ask } } });
}

function readMetadataAskId(message: SlackMessage): string | undefined {
  const ask = message.metadata?.event_payload?.ask;
  return ask && typeof ask === "object" && typeof (ask as { id?: unknown }).id === "string" ? (ask as { id: string }).id : undefined;
}

function validAsk(ask: Ask): boolean {
  return ask.answers.length >= 2 && ask.answers.length <= 10 && ask.answers.every((answer) => answer.trim().length > 0 && answer.length <= 64) && new Set(ask.answers).size === ask.answers.length;
}

function reactionsFor(ask: Ask): readonly string[] {
  return ask.form === "approval" ? APPROVAL_REACTIONS : ask.form === "choice" ? KEYCAPS.slice(0, ask.answers.length) : [...KEYCAPS.slice(0, ask.answers.length), SUBMIT_REACTION];
}

function sameAnswers(left: readonly string[], right: readonly string[]): boolean {
  return left.length === right.length && left.every((answer, index) => answer === right[index]);
}

function renderAsk(text: string, ask: Ask, fallback: boolean): string {
  const answers = ask.answers.map((answer, index) => `${fallback ? `${index + 1}.` : ask.form === "approval" ? (index === 0 ? "✅" : "❌") : `${index + 1}️⃣`} ${answer}`);
  return [text === ask.prompt ? "" : text, ask.prompt, ...answers].filter(Boolean).join("\n");
}

/**
 * Whether a file was already downloaded, marking it used if so: retention
 * counts from the last use. One pruned between the look and the touch is a
 * miss, and is fetched again.
 */
function keptAgain(target: string): boolean {
  const now = new Date();
  try {
    fs.utimesSync(target, now, now);
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
    throw error;
  }
}

/**
 * Removes files older than `cutoff`, then the directories they leave empty.
 * The forgotten markers directly under `files/` are kept for good: a stale
 * reference read later must still find one. Anything deeper is an attachment,
 * whatever it is called, and ages like one.
 */
function pruneFiles(directory: string, cutoff: number, top = true): number {
  let removed = 0;
  for (const entry of direntsOf(directory)) {
    const full = path.join(directory, entry.name);
    if (entry.isDirectory()) {
      removed += pruneFiles(full, cutoff, false);
      removeIfEmpty(full);
    } else if (!(top && entry.name.endsWith(".forgotten")) && removeIfStale(full, cutoff)) {
      removed += 1;
    }
  }
  return removed;
}

/**
 * Moves the file aside, then asks its age again, and puts it back if a
 * reader touched it first. A reader's touch lands either before the move —
 * seen here, and the file stays — or after it, where it misses and the file
 * is fetched again; so a path a reader was handed is never removed under it.
 */
function removeIfStale(file: string, cutoff: number): boolean {
  // Another prune may have taken any of these first; then it is handled.
  const before = mtimeOf(file);
  if (before === undefined || before >= cutoff) return false;
  const aside = `${file}.${randomUUID()}.pruning`;
  if (!ignoringGone(() => fs.renameSync(file, aside))) return false;
  const after = mtimeOf(aside);
  if (after === undefined) return false;
  if (after >= cutoff) {
    ignoringGone(() => fs.renameSync(aside, file));
    return false;
  }
  fs.rmSync(aside, { force: true });
  return true;
}

function mtimeOf(file: string): number | undefined {
  try {
    return fs.statSync(file).mtimeMs;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined;
    throw error;
  }
}

/** Runs it; false when what it touched was already gone. */
function ignoringGone(act: () => void): boolean {
  try {
    act();
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
    throw error;
  }
}

/** Removes the files of every thread a marker says was forgotten; idempotent. */
function sweepForgotten(directory: string): void {
  for (const entry of direntsOf(directory)) {
    if (!entry.isFile() || !entry.name.endsWith(".forgotten")) continue;
    fs.rmSync(path.join(directory, entry.name.slice(0, -".forgotten".length)), { recursive: true, force: true });
  }
}

function direntsOf(directory: string): fs.Dirent[] {
  try {
    return fs.readdirSync(directory, { withFileTypes: true });
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw error;
  }
}

/** A download may be filling it again right now; then it is not empty. */
function removeIfEmpty(directory: string): void {
  try {
    fs.rmdirSync(directory);
  } catch (error) {
    const code = (error as NodeJS.ErrnoException).code;
    if (code !== "ENOTEMPTY" && code !== "EEXIST" && code !== "ENOENT") throw error;
  }
}

/**
 * Slack's `ts` is seconds with a microsecond fraction, read exactly: a reply
 * a fraction of a millisecond after `since` is still after it.
 */
function tsToMicros(ts: string): number {
  const [seconds = "0", fraction = ""] = ts.split(".");
  return Number(seconds) * 1_000_000 + Number(fraction.padEnd(6, "0").slice(0, 6));
}

/**
 * A reply's instant to the microsecond, as ISO 8601 with six fractional
 * digits. Handed back as the next `since` it is exactly the reply's, so the
 * reply is not returned twice and one a microsecond later is not lost.
 */
function microsToInstant(micros: number): string {
  const iso = new Date(Math.floor(micros / 1000)).toISOString();
  return iso.replace(/Z$/, `${String(micros % 1000).padStart(3, "0")}Z`);
}

/** An instant to the microsecond: the digits past the millisecond are read too. */
function instantToMicros(instant: string): number {
  const ms = Date.parse(instant);
  if (Number.isNaN(ms)) return Number.NaN;
  const extra = /\.\d{3}(\d{1,3})Z$/.exec(instant)?.[1] ?? "";
  return ms * 1000 + Number(extra.padEnd(3, "0"));
}

/** Exact, where going through milliseconds would drop the last three digits. */
function microsToTs(micros: number): string {
  return `${Math.floor(micros / 1_000_000)}.${String(micros % 1_000_000).padStart(6, "0")}`;
}

function msToTs(ms: number): string {
  return (ms / 1000).toFixed(6);
}

/** A name from a message, made into one path segment. */
function safeName(name: string): string {
  const cleaned = name.replace(/[^A-Za-z0-9._-]/g, "_").replace(/^\.+/, "_");
  return cleaned || "file";
}

function messageOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

import { randomUUID } from "node:crypto";
import fs from "node:fs";
import path from "node:path";

/**
 * One generation of a work item's thread: its root `ts` once Slack answered,
 * the owner still posting it, or a tombstone left by whoever is forgetting it.
 */
export interface ThreadEntry {
  channel?: string;
  ts?: string;
  /** When the first attempt of this chain was about to post. */
  pendingSince?: number;
  /** `<pid>:<uuid>` of the attempt still posting or forgetting; absent once released. */
  owner?: string;
  /** This work is being forgotten; nothing before it counts any more. */
  tombstone?: true;
  /** The root a tombstone is forgetting, so a retry can finish the job. */
  covers?: string;
}

export interface ThreadMapOptions {
  /** How long to wait for a live owner to finish before failing. */
  maxWaitMs?: number;
  pollMs?: number;
  /** How long an owner's claim holds without being renewed. */
  leaseMs?: number;
  /** Told a root a newer one replaced, in another channel, so its files can go. */
  onDisplaced?: (ts: string) => void;
  /** Inspection reads an existing map without creating or tightening directories. */
  readOnly?: boolean;
}

/**
 * What `start` is told: when an earlier attempt that may have posted began.
 * It answers the root, and whether it posted it or found one already there.
 */
export type StartRoot = (recoverSince: number | undefined) => Promise<{ ts: string; posted: boolean }>;

/** Takes back a root this process posted after somebody else's replaced its claim. */
export type DiscardRoot = (ts: string) => Promise<void>;

interface Generation {
  n: number;
  entry: ThreadEntry;
  mtimeMs: number;
}

/**
 * `workId → thread` on disk, shared by every process that mounts the plugin.
 *
 * The state directory is machine-wide, so several daemons use it at once.
 * Each work item is a chain of numbered generations, `threads/<id>/<n>.json`,
 * and a generation is created exclusively — written aside and linked into
 * place — so exactly one process wins each number. Everything that changes
 * what a chain means claims the next number first: posting a root, taking
 * over from an owner that died, and forgetting the work, which leaves a
 * tombstone and re-checks under it before removing anything.
 *
 * An owner holds its claim by lease: its generation's mtime is renewed while
 * it works, and a claim whose lease ran out is dead even if some other
 * process now has its pid.
 */
export class ThreadMap {
  private readonly root: string;
  private readonly maxWaitMs: number;
  private readonly pollMs: number;
  private readonly leaseMs: number;
  private readonly onDisplaced: (ts: string) => void;
  /** Which work a root belongs to, as far as this process has seen. */
  private readonly workOf = new Map<string, string>();

  constructor(directory: string, options: ThreadMapOptions = {}) {
    this.root = path.join(directory, "threads");
    // An owner may be waiting out Slack's one-a-minute limit several times.
    this.maxWaitMs = options.maxWaitMs ?? 10 * 60_000;
    this.pollMs = options.pollMs ?? 100;
    this.leaseMs = options.leaseMs ?? 60_000;
    this.onDisplaced = options.onDisplaced ?? (() => {});
    // What threads a machine's work lives in is nobody else's to read.
    if (!options.readOnly) {
      privateDirectory(directory);
      privateDirectory(this.root);
    }
  }

  /**
   * The thread this work already has in `channel`, if it has one.
   *
   * Asking counts as using it. The touch comes before looking for a
   * tombstone, so a forget racing this either sees the touch and backs off,
   * or left its tombstone first and this answers that there is no thread.
   */
  known(workId: string, channel: string): string | undefined {
    requireId(workId);
    const current = this.current(workId);
    const ts = inChannel(current, channel)?.ts;
    if (!ts) return undefined;
    touch(this.file(workId, current!.n));
    // Numbers come back after a forget, so the same number is not the same
    // claim: it has to still carry the same root, and still be the newest.
    if (this.read(workId, current!.n)?.entry.ts !== ts) return undefined;
    if (Math.max(0, ...this.generations(workId)) !== current!.n) return undefined;
    this.workOf.set(ts, workId);
    return ts;
  }

  /** Marks the thread with this root as used, so reading its replies keeps it. */
  used(ts: string): void {
    const workId = this.workOf.get(ts) ?? this.findWork(ts);
    if (!workId) return;
    // The generation carrying it, even under a tombstone: a forget's second
    // look reads that generation, so a use now makes it back off.
    const carrying = this.settled(workId);
    if (carrying?.entry.ts === ts) touch(this.file(workId, carrying.n));
  }

  /**
   * Forgets one work item's thread, returning the root it had, if any.
   *
   * The thread stays in Slack; only this machine's memory of it goes, so the
   * next `open` for the same work starts a new one.
   */
  forget(workId: string): string | undefined {
    requireId(workId);
    const outcome = this.retire(workId, (generation) => !this.isLive(generation));
    if (outcome === "busy") {
      // Its root may be reaching Slack right now; forgetting it would leave
      // that root with no memory, and the next open would post a second.
      throw new Error(`the thread for ${workId} is being opened right now; forget it once that finishes`);
    }
    return outcome;
  }

  /**
   * Forgets every settled thread nobody used since `cutoffMs`, returning the
   * roots it forgot. An attempt whose owner still holds its lease is never
   * pruned, however old.
   */
  prune(cutoffMs: number): string[] {
    const stale = (generation: Generation) =>
      !generation.entry.tombstone && !this.isLive(generation) && generation.mtimeMs < cutoffMs;

    const forgotten: string[] = [];
    for (const name of entriesOf(this.root)) {
      if (name.startsWith(".")) continue;
      const outcome = this.retire(Buffer.from(name, "base64url").toString(), stale);
      if (outcome && outcome !== "busy") forgotten.push(outcome);
    }
    return forgotten;
  }

  /** The work's thread in `channel`, posting its root through `start` only if nobody has. */
  async open(workId: string, channel: string, start: StartRoot, discard: DiscardRoot = async () => {}): Promise<string> {
    requireId(workId);
    const deadline = Date.now() + this.maxWaitMs;
    // What this open has lost so far: the claim, to tell a winner from a
    // forget, and a root it posted after losing it, taken back only once the
    // winner's is known — and only if the winner did not settle on it.
    const lost: Lost = {};
    for (;;) {
      const step = await this.step(workId, channel, start, lost);
      if (step.kind === "wait") {
        if (Date.now() >= deadline) throw new Error(`another amy is still working on the thread for ${workId}`);
        await new Promise((resolve) => setTimeout(resolve, this.pollMs));
        continue;
      }
      if (step.kind === "again") continue;
      if (lost.posted && lost.posted !== step.ts) await discard(lost.posted);
      if (step.kind === "forgotten") {
        throw new Error(`the thread for ${workId} was forgotten while it was being opened`);
      }
      return step.ts;
    }
  }

  /** One look at the chain, and what the open does next because of it. */
  private async step(workId: string, channel: string, start: StartRoot, lost: Lost): Promise<Step> {
    const top = this.current(workId);
    // Forgotten while this open's post was out: nobody asked for a thread
    // after that, so none is started — the late root is taken back.
    if (lost.claim !== undefined && this.forgottenSince(workId, lost.claim, top)) return { kind: "forgotten" };
    if (this.mustWaitOn(top)) return { kind: "wait" };

    // Under a tombstone whose owner died mid-forget, the thread it covered
    // is still the thread: adopted, not replaced by a second root.
    const settled = this.settled(workId);
    const entry = inChannel(settled, channel);
    if (entry?.ts) {
      if (top!.n !== settled!.n && !this.resettle(workId, top!.n + 1, channel, entry.ts)) return { kind: "again" };
      this.workOf.set(entry.ts, workId);
      return { kind: "thread", ts: entry.ts };
    }

    const claim = (top?.n ?? 0) + 1;
    const outcome = await this.attempt(workId, channel, claim, entry?.pendingSince, start);
    if (outcome?.won) return { kind: "thread", ts: outcome.ts };
    if (outcome) lost.claim = claim;
    if (outcome?.posted) lost.posted = outcome.ts;
    return { kind: "again" };
  }

  /**
   * Whether a released tombstone now stands above the claim this open lost,
   * with no thread settled above that claim: a forget, not a winner.
   */
  private forgottenSince(workId: string, lostClaim: number, top: Generation | undefined): boolean {
    if (!top?.entry.tombstone || this.isLive(top) || top.n <= lostClaim) return false;
    const settled = this.settled(workId);
    return !settled || settled.n < lostClaim;
  }

  /**
   * Creates `n` exclusively and keeps it only if it is then the newest.
   *
   * Compaction frees numbers under a settled result, so an owner stalled past
   * its lease can still win an exclusive create of its number after a taker
   * published above it and cleared its claim. That create can only succeed
   * once the taker's result exists, so the check after it always sees it.
   */
  private publish(workId: string, n: number, entry: ThreadEntry): boolean {
    if (!this.create(workId, n, entry)) return false;
    if (Math.max(0, ...this.generations(workId)) === n) return true;
    fs.rmSync(this.file(workId, n), { force: true });
    return false;
  }

  /** Writes a known root again above a dead tombstone, clearing what is under it. */
  private resettle(workId: string, next: number, channel: string, ts: string): boolean {
    if (!this.create(workId, next, { channel, ts })) return false;
    this.removeBelow(workId, next);
    return true;
  }

  /**
   * A live owner still posting a root — for any channel: one for the old
   * channel finishing after a newer generation settled would hand back a
   * thread that is no longer current — or a live tombstone.
   */
  private mustWaitOn(current: Generation | undefined): boolean {
    return current !== undefined && !current.entry.ts && this.isLive(current);
  }

  /**
   * One attempt at generation `next`: undefined when somebody else won the
   * number; otherwise the root it posted or recovered, and whether its claim
   * was still its own when the answer came back.
   */
  private async attempt(
    workId: string,
    channel: string,
    next: number,
    recoverSince: number | undefined,
    start: StartRoot,
  ): Promise<{ ts: string; posted: boolean; won: boolean } | undefined> {
    // Once, before the post: a failure reported later must not move it.
    const pendingSince = recoverSince ?? Date.now();
    const owner = `${process.pid}:${randomUUID()}`;
    if (!this.create(workId, next, { channel, pendingSince, owner })) return undefined;

    const renew = setInterval(() => touch(this.file(workId, next)), Math.max(1, Math.floor(this.leaseMs / 4)));
    renew.unref();
    let ts: string;
    let posted: boolean;
    try {
      ({ ts, posted } = await start(recoverSince));
    } catch (error) {
      // Released as the next generation, not removed: Slack may have taken
      // the root before the call failed, and the next attempt recovers from
      // this instant. If the number is gone, somebody already moved on.
      this.publish(workId, next + 1, { channel, pendingSince });
      throw error;
    } finally {
      clearInterval(renew);
    }
    // Published as the next generation, created exclusively, never written
    // over the claim: if a taker, a tombstone or anyone else took that number
    // first, this claim was lost while the post was out. The open then reads
    // what the newer claim settles on, and takes this root back only if it
    // posted it and the winner did not recover that very root.
    const result = next + 1;
    if (!this.publish(workId, result, { channel, ts })) return { ts, posted, won: false };
    const displaced = this.rootsBelow(workId, result).filter((older) => older !== ts);
    this.removeBelow(workId, result);
    for (const older of displaced) {
      this.workOf.delete(older);
      this.onDisplaced(older);
    }
    this.workOf.set(ts, workId);
    return { ts, posted, won: true };
  }

  /**
   * Forgets a work item when `shouldGo` holds, asked again under a tombstone.
   *
   * The tombstone is the next generation, created exclusively, so nobody can
   * post or take over while it stands, and it names the root it covers. If
   * what it covers changed before the tombstone landed — touched, or taken —
   * the forget backs off and removes only its own tombstone. A tombstone left
   * by a forget that died is stepped over: the thread under it is the one
   * decided on again, so a retry finishes the job it started.
   */
  private retire(workId: string, shouldGo: (generation: Generation) => boolean): string | "busy" | undefined {
    const top = this.current(workId);
    if (!top) return undefined;
    if (this.isLive(top)) return "busy";
    const subject = this.settled(workId);
    // Nothing under a floor or a dead tombstone: nothing left to forget.
    if (!subject) return undefined;
    if (!shouldGo(subject)) return "busy";

    const tombstone = top.n + 1;
    const claim = { tombstone: true as const, owner: `${process.pid}:${randomUUID()}`, covers: subject?.entry.ts };
    if (!this.create(workId, tombstone, claim)) return "busy";

    const covered = this.read(workId, subject.n);
    if (!covered || !shouldGo(covered)) {
      fs.rmSync(this.file(workId, tombstone), { force: true });
      return "busy";
    }
    this.removeBelow(workId, tombstone);
    // Kept, released, as the chain's floor: numbers never come back, so a
    // request that outlived its claim can never publish over a newer one.
    this.release(workId, tombstone, { tombstone: true, covers: covered.entry.ts });
    const ts = covered.entry.ts;
    if (ts) this.workOf.delete(ts);
    return ts;
  }

  private isLive(generation: Generation): boolean {
    const owner = generation.entry.owner;
    if (!owner) return false;
    return Date.now() - generation.mtimeMs < this.leaseMs && isAlive(pidOf(owner));
  }

  /** The newest generation that is not a tombstone: the thread, or its attempt. */
  private settled(workId: string): Generation | undefined {
    const numbers = this.generations(workId).sort((a, b) => b - a);
    for (const n of numbers) {
      const generation = this.read(workId, n);
      if (generation && !generation.entry.tombstone) return generation;
    }
    return undefined;
  }

  /** Every root recorded under generation `n`. */
  private rootsBelow(workId: string, n: number): string[] {
    return this.generations(workId)
      .filter((older) => older < n)
      .map((older) => this.read(workId, older)?.entry.ts)
      .filter((ts): ts is string => ts !== undefined);
  }

  private current(workId: string): Generation | undefined {
    const n = Math.max(0, ...this.generations(workId));
    if (n === 0) return undefined;
    // Removed by the owner that superseded it between the listing and the read.
    return this.read(workId, n) ?? this.current(workId);
  }

  /** One generation, or nothing if it is gone; anything else is a real problem. */
  private read(workId: string, n: number): Generation | undefined {
    const file = this.file(workId, n);
    try {
      const mtimeMs = fs.statSync(file).mtimeMs;
      return { n, entry: JSON.parse(fs.readFileSync(file, "utf8")) as ThreadEntry, mtimeMs };
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined;
      throw error;
    }
  }

  private findWork(ts: string): string | undefined {
    for (const name of entriesOf(this.root)) {
      if (name.startsWith(".")) continue;
      const workId = Buffer.from(name, "base64url").toString();
      // The settled generation, not the top: under a tombstone, the thread
      // it covers is still the one a held reference is using.
      if (this.settled(workId)?.entry.ts === ts) {
        this.workOf.set(ts, workId);
        return workId;
      }
    }
    return undefined;
  }

  private generations(workId: string): number[] {
    return entriesOf(this.directoryOf(workId))
      .map((name) => /^(\d+)\.json$/.exec(name)?.[1])
      .filter((n): n is string => n !== undefined)
      .map(Number);
  }

  /**
   * Exclusive: false when somebody else already holds this number, or when
   * the chain's directory went away under a forget and has to be made again.
   */
  private create(workId: string, n: number, entry: ThreadEntry): boolean {
    privateDirectory(this.root);
    // Staged outside the chain, so a forget can always remove an empty one.
    const staged = path.join(this.root, `.${randomUUID()}.tmp`);
    fs.writeFileSync(staged, JSON.stringify(entry), { mode: 0o600 });
    try {
      fs.mkdirSync(this.directoryOf(workId), { recursive: true, mode: 0o700 });
      fs.linkSync(staged, this.file(workId, n));
      return true;
    } catch (error) {
      const code = (error as NodeJS.ErrnoException).code;
      if (code !== "EEXIST" && code !== "ENOENT") throw error;
      return false;
    } finally {
      fs.rmSync(staged, { force: true });
    }
  }

  /** Only by the tombstone's owner, whole and renamed into place. */
  private release(workId: string, n: number, entry: ThreadEntry): void {
    const staged = path.join(this.root, `.${randomUUID()}.tmp`);
    fs.writeFileSync(staged, JSON.stringify(entry), { mode: 0o600 });
    fs.renameSync(staged, this.file(workId, n));
  }

  /** Generations under `n` are settled history once `n` is decided. */
  private removeBelow(workId: string, n: number): void {
    for (const older of this.generations(workId)) {
      if (older < n) fs.rmSync(this.file(workId, older), { force: true });
    }
  }

  private directoryOf(workId: string): string {
    return path.join(this.root, Buffer.from(workId).toString("base64url"));
  }

  private file(workId: string, n: number): string {
    return path.join(this.directoryOf(workId), `${n}.json`);
  }
}

/** What an open lost along the way. */
interface Lost {
  claim?: number;
  posted?: string;
}

type Step =
  | { kind: "thread"; ts: string }
  | { kind: "wait" }
  | { kind: "again" }
  | { kind: "forgotten"; ts?: undefined };

/** The generation's entry when it is a thread in `channel`, not a tombstone. */
function inChannel(current: Generation | undefined, channel: string): ThreadEntry | undefined {
  return current && !current.entry.tombstone && current.entry.channel === channel ? current.entry : undefined;
}

/** Made if missing, and tightened if it was made looser before. */
export function privateDirectory(directory: string): void {
  fs.mkdirSync(directory, { recursive: true, mode: 0o700 });
  fs.chmodSync(directory, 0o700);
}

/** A directory's names, or none if a forget removed it a moment ago. */
function entriesOf(directory: string): string[] {
  try {
    return fs.readdirSync(directory);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw error;
  }
}

/** An empty id would name the whole `threads` directory. */
function requireId(workId: string): void {
  if (!workId) throw new Error("a work id is required, and an empty one would name every thread");
}

/** Renews a claim or a last use; a file gone meanwhile has nothing to keep. */
function touch(file: string): void {
  const now = new Date();
  try {
    fs.utimesSync(file, now, now);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
  }
}

function pidOf(owner: string): number {
  return Number(owner.split(":")[0]);
}

function isAlive(pid: number): boolean {
  if (!Number.isInteger(pid) || pid <= 0) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    // EPERM: it exists and belongs to somebody else.
    return (error as NodeJS.ErrnoException).code === "EPERM";
  }
}

import { ConfigSchema } from "@amykit/core";
import { DEFAULT_RATE_LIMIT_RETRIES, DEFAULT_RETRY_AFTER_S } from "./SlackApi.js";
import { DEFAULT_MARKS, DEFAULT_RETENTION_DAYS } from "./SlackConversation.js";

/** What this plugin needs told to it, and nothing more. */
export const configSchema = {
  channel: {
    type: "string",
    required: true,
    description: "the channel id every work thread opens in, such as C0XXXXXXX — an id, not a name",
    example: "C0XXXXXXX",
  },
  token: {
    type: "string",
    required: true,
    description: "where the bot token lives: `env:SLACK_BOT_TOKEN` or `file:<path>#<KEY>`, never the token itself",
    example: "env:SLACK_BOT_TOKEN",
  },
  operator: {
    type: "string",
    required: true,
    description: "the user id, such as U0XXXXXXX, whose replies are answers; everybody else's are ignored",
    example: "U0XXXXXXX",
  },
  maxRateLimitRetries: {
    type: "number",
    description: "how many times a call Slack rate limits (HTTP 429) is waited out and tried again before it fails",
    default: DEFAULT_RATE_LIMIT_RETRIES,
  },
  defaultRetryAfterSeconds: {
    type: "number",
    description: "how long to wait after a 429 that carries no Retry-After; one names its own wait, and that wins",
    default: DEFAULT_RETRY_AFTER_S,
  },
  directory: {
    type: "string",
    description: "where each work item's thread is remembered, relative to the state directory",
    default: "slack",
  },
  retentionDays: {
    type: "number",
    description:
      "days a downloaded file or a thread's memory stays unused before it is pruned, 0 to keep everything. A pruned file is fetched again when its reply is read; a pruned thread means the next question opens a new one",
    default: DEFAULT_RETENTION_DAYS,
  },
  decisionReaction: {
    type: "string",
    description:
      "the reaction, by emoji name, the operator puts on their own reply to mark it as the decision that moves the work. A reaction Slack lists only in part is read again in full with reactions.get, which needs reactions:read",
    default: DEFAULT_MARKS.decision,
  },
  discussionReaction: {
    type: "string",
    description:
      "the reaction, by emoji name, the operator puts on their own reply to mark it as a turn in a discussion, answered in the thread while the work waits",
    default: DEFAULT_MARKS.discussion,
  },
} satisfies ConfigSchema;

export { plugin } from "./plugin.js";
export { configSchema } from "./config.js";
export { DEFAULT_RETENTION_DAYS, SlackConversation } from "./SlackConversation.js";
export type { SlackCheck, SlackConversationOptions } from "./SlackConversation.js";
export { DEFAULT_RATE_LIMIT_RETRIES, DEFAULT_RETRY_AFTER_S, SLACK_API, SlackApi, TooLarge, fetchTransport } from "./SlackApi.js";
export type { HttpRequest, HttpResponse, HttpTransport, SlackAnswer, SlackApiOptions } from "./SlackApi.js";
export { resolveToken } from "./secret.js";
export type { SecretSources } from "./secret.js";

import path from "node:path";
import { definePlugin } from "@amykit/core";
import { configSchema } from "./config.js";
import { resolveToken } from "./secret.js";
import { DEFAULT_RATE_LIMIT_RETRIES, DEFAULT_RETRY_AFTER_S, SlackApi } from "./SlackApi.js";
import { DEFAULT_MARKS, DEFAULT_RETENTION_DAYS, SlackConversation } from "./SlackConversation.js";

export const plugin = definePlugin<typeof configSchema>({
  name: "@amykit/plugin-slack",
  configSchema,
  register(registry, ctx) {
    const channel = ctx.config.channel;
    const operator = ctx.config.operator;
    // Refused at mount, naming the setting: a name where an id belongs is a
    // thread posted nowhere, found only by waiting for an answer.
    if (!/^[CG][A-Z0-9]+$/.test(channel)) {
      throw new Error(`@amykit/plugin-slack: \`channel\` must be a channel id such as C0XXXXXXX, got ${channel}`);
    }
    if (!/^[UW][A-Z0-9]+$/.test(operator)) {
      throw new Error(`@amykit/plugin-slack: \`operator\` must be a user id such as U0XXXXXXX, got ${operator}`);
    }

    // The host applies the schema's defaults; a caller that did not still mounts the same thing.
    const retries = (ctx.config.maxRateLimitRetries) ?? DEFAULT_RATE_LIMIT_RETRIES;
    const fallback = (ctx.config.defaultRetryAfterSeconds) ?? DEFAULT_RETRY_AFTER_S;
    const retentionDays = (ctx.config.retentionDays) ?? DEFAULT_RETENTION_DAYS;
    for (const [name, value] of Object.entries({ maxRateLimitRetries: retries, defaultRetryAfterSeconds: fallback, retentionDays })) {
      if (!Number.isFinite(value) || value < 0) {
        throw new Error(`@amykit/plugin-slack: \`${name}\` must be zero or more, got ${value}`);
      }
    }

    const api = new SlackApi(resolveToken(ctx.config.token), {
      maxRateLimitRetries: Math.floor(retries),
      defaultRetryAfterSeconds: fallback,
    });
    registry.port(
      "conversation",
      new SlackConversation(api, {
        channel,
        operator,
        directory: path.join(ctx.paths.state, (ctx.config.directory) ?? "slack"),
        retentionDays,
        marks: {
          decision: (ctx.config.decisionReaction) ?? DEFAULT_MARKS.decision,
          discussion: (ctx.config.discussionReaction) ?? DEFAULT_MARKS.discussion,
        },
        readOnly: ctx.readOnly,
        now: ctx.now,
      }),
    );
  },
});

import fs from "node:fs";
import os from "node:os";
import path from "node:path";

export interface SecretSources {
  env: NodeJS.ProcessEnv;
  readFile: (file: string) => string;
}

const FROM_DISK: SecretSources = {
  env: process.env,
  readFile: (file) => fs.readFileSync(file, "utf8"),
};

/**
 * The bot token, from where the config says it lives.
 *
 * `env:<NAME>` or `file:<path>#<KEY>`, and nothing else. A token written into
 * `config.yaml` itself is refused rather than used, because that file is the
 * one people paste into an issue when something breaks.
 */
export function resolveToken(ref: string, sources: SecretSources = FROM_DISK): string {
  if (ref.startsWith("env:")) {
    const name = ref.slice("env:".length);
    const value = sources.env[name];
    if (!value) throw new Error(`@amykit/plugin-slack: \`token\` names ${name}, which is not set`);
    return value;
  }

  if (ref.startsWith("file:")) {
    const [file = "", key = ""] = ref.slice("file:".length).split("#");
    if (!file || !key) {
      throw new Error("@amykit/plugin-slack: `token` must be `file:<path>#<KEY>`, naming the key inside the file");
    }
    const value = keyIn(sources.readFile(expandHome(file)), key);
    if (!value) throw new Error(`@amykit/plugin-slack: ${file} has no ${key}`);
    return value;
  }

  throw new Error(
    "@amykit/plugin-slack: `token` must say where the token lives — `env:SLACK_BOT_TOKEN` or " +
      "`file:<path>#<KEY>` — and is never written into the config itself",
  );
}

/** One `KEY=value` line of a dotenv-shaped file, quotes stripped. */
function keyIn(text: string, key: string): string | undefined {
  for (const line of text.split(/\r?\n/)) {
    const equals = line.indexOf("=");
    if (equals === -1) continue;
    const name = line.slice(0, equals).trim().replace(/^export\s+/, "");
    if (name !== key) continue;
    return unquote(line.slice(equals + 1).trim());
  }
  return undefined;
}

function unquote(value: string): string {
  const quote = value[0];
  return (quote === '"' || quote === "'") && value.length > 1 && value.endsWith(quote) ? value.slice(1, -1) : value;
}

function expandHome(file: string): string {
  return file === "~" || file.startsWith("~/") ? path.join(os.homedir(), file.slice(1)) : file;
}
